#!/usr/bin/env bash
# CLUB ACCOUNT SERVER - STEP 2: student storage, sign-ups, the admin page and laptop control.
# Run on the server AFTER club-server-setup.sh (step 1) showed all green:
#     sudo bash club-server-step2.sh
# Safe to run again: it updates the program and skips what is already done.
set -euo pipefail

say()  { printf '\n\033[1;36m%s\033[0m\n' "$*"; }
ok()   { printf '  \033[1;32mOK\033[0m    %s\n' "$*"; }
bad()  { printf '  \033[1;31mFAIL\033[0m  %s\n' "$*"; FAILS=$((FAILS + 1)); }
die()  { printf '\n\033[1;31mSTOPPED: %s\033[0m\n' "$*"; exit 1; }
ask()  { local a; read -r -p "$1 " a </dev/tty; echo "$a"; }
has_text() { grep -qi -- "$2" <<<"$1"; }
FAILS=0
PORT=8443

[ "$(id -u)" = "0" ] || die "Run it with sudo:  sudo bash club-server-step2.sh"
[ -f /var/lib/samba/private/sam.ldb ] || die "Step 1 has not been run on this machine yet. Run club-server-setup.sh first."
systemctl is-active --quiet samba-ad-dc || die "The account service from step 1 is not running. Run:  systemctl start samba-ad-dc"

REALM="$(testparm -s --parameter-name=realm 2>/dev/null | tr -d '[:space:]')"
NETBIOS="$(testparm -s --parameter-name=workgroup 2>/dev/null | tr -d '[:space:]')"
[ -n "$REALM" ] && [ -n "$NETBIOS" ] || die "Could not read the domain name from Samba."
REALM_LC="$(echo "$REALM" | tr '[:upper:]' '[:lower:]')"
BASE_DN="DC=$(echo "$REALM_LC" | sed 's/\./,DC=/g')"
HOST_SHORT="$(hostname -s)"
SERVER_NAME="$HOST_SHORT.$REALM_LC"
DEV="$(ip -4 route show default | awk '{print $5; exit}')"
CIDR_ADDR="$(ip -o -4 addr show dev "$DEV" scope global | awk '{print $4; exit}')"
IP="${CIDR_ADDR%/*}"
NETWORK="$(python3 -c "import ipaddress,sys; print(ipaddress.ip_interface(sys.argv[1]).network)" "$CIDR_ADDR")"
ALLOW_FROM="${CLUB_ALLOW_FROM:-$(awk '/^allow /{print $2; exit}' /etc/chrony/chrony.conf 2>/dev/null || true)}"
[ -n "$ALLOW_FROM" ] || ALLOW_FROM="$NETWORK"
echo "  Server $SERVER_NAME ($IP), domain $REALM, laptops allowed from $ALLOW_FROM"

sid_of() { wbinfo -n "$NETBIOS\\$1" | awk '{print $1}'; }

command -v curl >/dev/null 2>&1 || { export DEBIAN_FRONTEND=noninteractive; apt-get install -y -q curl >/dev/null; }

# ---------- 1. Storage ----------
say "1 of 7  Storage for student files"
install -d -m 755 /srv/club /srv/club/students /srv/club/profiles
install -d -m 700 /srv/club/removed /srv/club/files /srv/club/shots /srv/club/backups /srv/club/assets /etc/club /etc/club/tls /var/lib/club /opt/club
install -d -m 2775 /srv/club/competition
ADMIN_GID="$(wbinfo -Y "$(sid_of ClubAdmins)" 2>/dev/null || true)"
if [ -n "$ADMIN_GID" ]; then chgrp "$ADMIN_GID" /srv/club/competition; chmod 2775 /srv/club/competition; ok "admins can add competition images"
else echo "  (could not look up the ClubAdmins group yet - competition share is root-only for now)"; fi
ok "folders ready in /srv/club ($(df -h --output=avail /srv/club | tail -1 | tr -d ' ') free)"

# ---------- 2. Shares ----------
say "2 of 7  Network shares"
if ! grep -q "club shares" /etc/samba/smb.conf; then
  cat >> /etc/samba/smb.conf <<EOF

# club shares (added by club-server-step2.sh)
[students\$]
    comment = Student files (drive H: on the laptops)
    path = /srv/club/students
    read only = no
    browseable = no
    csc policy = disable

[profiles\$]
    comment = Student settings that follow them between laptops
    path = /srv/club/profiles
    read only = no
    browseable = no
    csc policy = disable

[competition]
    comment = Competition images (admins write, laptops read)
    path = /srv/club/competition
    read only = no
    valid users = @"$NETBIOS\\ClubAdmins" @"$NETBIOS\\Domain Computers" @"$NETBIOS\\Domain Admins"
    write list = @"$NETBIOS\\ClubAdmins" @"$NETBIOS\\Domain Admins"
    force create mode = 0664
    force directory mode = 2775
EOF
  testparm -s >/dev/null 2>&1 || die "The share settings were not accepted. Run:  testparm"
  smbcontrol all reload-config >/dev/null 2>&1 || systemctl restart samba-ad-dc
fi
ok "students\$, profiles\$ and competition are shared"

# Browsers tag every download as "came from the internet" (a small hidden second part of the file). The student shares must be
# able to store that tag, or every download into drive H: fails with "something went wrong".
if grep -q "streams_xattr" /etc/samba/smb.conf; then
  ok "shares can store download tags"
elif ! setfattr -n user.clubtest -v 1 /srv/club/students 2>/dev/null; then
  bad "this disk does not allow the file tags browsers need, so downloads into H: will keep failing (send a photo of this)"
else
  setfattr -x user.clubtest /srv/club/students 2>/dev/null || true
  can_list() { smbclient '//localhost/students$' -P -c 'ls' >/dev/null 2>&1; }
  wait_samba() { for _ in $(seq 1 20); do systemctl is-active --quiet samba-ad-dc && wbinfo -p >/dev/null 2>&1 && return 0; sleep 2; done; return 1; }
  BEFORE=no; if can_list; then BEFORE=yes; fi
  cp -p /etc/samba/smb.conf /etc/samba/smb.conf.before-streams
  sed -i '/^    csc policy = disable$/a\    vfs objects = dfs_samba4 acl_xattr streams_xattr' /etc/samba/smb.conf
  GOOD=yes
  testparm -s >/dev/null 2>&1 || GOOD=no
  if [ "$GOOD" = yes ]; then
    systemctl restart samba-ad-dc || true
    wait_samba || GOOD=no
    sleep 3
    if [ "$GOOD" = yes ] && [ "$BEFORE" = yes ] && ! can_list; then GOOD=no; fi
  fi
  if [ "$GOOD" = yes ]; then
    ok "shares can now store download tags (restart any laptop that is switched on, so it reconnects)"
  else
    cp -p /etc/samba/smb.conf.before-streams /etc/samba/smb.conf
    systemctl restart samba-ad-dc || true
    wait_samba || true
    bad "the download fix was not accepted by this server, so it was undone and the shares are as before (send a photo of this)"
  fi
fi

# ---------- 3. The account laptops use to join ----------
say "3 of 7  Join account for laptops"
umask 077
if [ ! -f /etc/club/join.pass ]; then
  JOIN_PASS="$(openssl rand -base64 24 | tr -d '/+=' | cut -c1-24)aA1"
  if samba-tool user show svc-join >/dev/null 2>&1; then
    samba-tool user setpassword svc-join --newpassword="$JOIN_PASS" >/dev/null
  else
    samba-tool user create svc-join "$JOIN_PASS" --userou="OU=ServiceAccounts" --description="Only allowed to add laptops to the Laptops folder" >/dev/null
  fi
  samba-tool user setexpiry svc-join --noexpiry >/dev/null 2>&1 || true
  printf '%s' "$JOIN_PASS" > /etc/club/join.pass
  JOIN_SID="$(sid_of svc-join)"
  samba-tool dsacl set --objectdn="OU=Laptops,$BASE_DN" \
    --sddl="(OA;CI;CCDC;bf967a86-0de6-11d0-a285-00aa003049e2;;$JOIN_SID)(OA;CIIO;GA;;bf967a86-0de6-11d0-a285-00aa003049e2;$JOIN_SID)" >/dev/null \
    || die "Could not give the join account its one permission."
  ldbmodify -H /var/lib/samba/private/sam.ldb >/dev/null <<EOF
dn: $BASE_DN
changetype: modify
replace: ms-DS-MachineAccountQuota
ms-DS-MachineAccountQuota: 0
EOF
fi
[ -f /etc/club/join.key ] || openssl rand -hex 24 > /etc/club/join.key
ok "svc-join can add laptops to the Laptops folder and nothing else; students cannot join their own machines"

# ---------- 4. Certificate (so sign-ups and the admin page are encrypted) ----------
say "4 of 7  Encryption certificate"
T=/etc/club/tls
if [ ! -f "$T/server.crt" ]; then
  openssl req -x509 -newkey rsa:3072 -nodes -days 3650 -keyout "$T/ca.key" -out "$T/ca.crt" -subj "/CN=Club Server Root ($REALM)" >/dev/null 2>&1
  openssl req -newkey rsa:2048 -nodes -keyout "$T/server.key" -out "$T/server.csr" -subj "/CN=$SERVER_NAME" >/dev/null 2>&1
  printf 'subjectAltName=DNS:%s,DNS:%s,IP:%s\nextendedKeyUsage=serverAuth\nbasicConstraints=CA:FALSE\n' "$SERVER_NAME" "$HOST_SHORT" "$IP" > "$T/ext.cnf"
  openssl x509 -req -in "$T/server.csr" -CA "$T/ca.crt" -CAkey "$T/ca.key" -CAcreateserial -days 1825 -extfile "$T/ext.cnf" -out "$T/server.crt" >/dev/null 2>&1
  chmod 600 "$T"/*.key
fi
ok "certificate made (laptops trust it once they run Join-Club)"

# ---------- 5. The program ----------
say "5 of 7  Installing the club program"
base64 -d > /opt/club/clubd.py <<'CLUBD_PAYLOAD'

CLUBD_PAYLOAD
base64 -d > /opt/club/Join-Club.template.cmd <<'TEMPLATE_PAYLOAD'

TEMPLATE_PAYLOAD
chmod 700 /opt/club
python3 - "$REALM" "$NETBIOS" "$SERVER_NAME" "$IP" "$ALLOW_FROM" "$PORT" <<'PYCONF'
import json, sys
realm, nb, name, ip, allow, port = sys.argv[1:7]
# Keep any extra networks (for example the school Wi-Fi range) that were added after the first setup.
try:
    old = [n.strip() for n in json.load(open("/etc/club/club.json")).get("allow_from", "").split(",") if n.strip()]
except Exception:
    old = []
allow = ",".join(dict.fromkeys([n.strip() for n in allow.split(",") if n.strip()] + old))
cfg = {
    "realm": realm, "netbios": nb, "server_name": name, "server_ip": ip, "allow_from": allow, "port": int(port),
    "join_user": "svc-join", "join_pass": open("/etc/club/join.pass").read().strip(), "join_key": open("/etc/club/join.key").read().strip(),
    "ca_pem": "/etc/club/tls/ca.crt", "tls_cert": "/etc/club/tls/server.crt", "tls_key": "/etc/club/tls/server.key",
    "dirs": {"students": "/srv/club/students", "profiles": "/srv/club/profiles", "competition": "/srv/club/competition", "removed": "/srv/club/removed", "files": "/srv/club/files", "shots": "/srv/club/shots", "assets": "/srv/club/assets"},
}
json.dump(cfg, open("/etc/club/club.json", "w"), indent=1)
PYCONF
chmod 600 /etc/club/club.json
python3 -c "import ast; ast.parse(open('/opt/club/clubd.py').read())" || die "The program file is damaged."
python3 -c "import samba.samdb, ldb, cgi" 2>/dev/null || die "This server's Python is missing the Samba pieces (python3-samba)."
cat > /etc/systemd/system/club.service <<EOF
[Unit]
Description=Club account server (sign-ups, admin page, laptop control)
After=samba-ad-dc.service network-online.target
Wants=samba-ad-dc.service

[Service]
ExecStart=/usr/bin/python3 -W ignore /opt/club/clubd.py
Restart=always
RestartSec=3
User=root
NoNewPrivileges=yes
PrivateTmp=yes
ProtectHome=yes
StandardOutput=append:/var/log/club.log
StandardError=append:/var/log/club.log

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable club.service >/dev/null 2>&1
systemctl restart club.service
for NET in $(python3 -c "import json; print(' '.join(n.strip() for n in json.load(open('/etc/club/club.json'))['allow_from'].split(',') if n.strip()))"); do
  ufw allow from "$NET" to any port "$PORT" proto tcp >/dev/null 2>&1 || true
done
ufw allow from "$ALLOW_FROM" to any port "$PORT" proto tcp >/dev/null 2>&1 || echo "  NOTE: could not open port $PORT in this machine's firewall (fine if the firewall is off or handled by Proxmox)."
ok "program installed and started"

# Nightly backup of every account and the admin page's data (kept 14 days), and automatic security updates.
cat > /usr/local/sbin/club-backup <<'BKP'
#!/usr/bin/env bash
set -u
D=/srv/club/backups/$(date +%F)
mkdir -p "$D"
samba-tool domain backup offline --targetdir="$D" >/dev/null 2>&1
python3 - "$D" <<'PY'
import sqlite3, sys
src = sqlite3.connect("/var/lib/club/club.db")
dst = sqlite3.connect(sys.argv[1] + "/club.db")
src.backup(dst)
PY
cp -a /etc/club "$D/etc-club" 2>/dev/null
find /srv/club/backups -mindepth 1 -maxdepth 1 -type d -mtime +14 -exec rm -rf {} +
BKP
chmod 700 /usr/local/sbin/club-backup
printf '15 3 * * * root /usr/local/sbin/club-backup\n' > /etc/cron.d/club-backup
DEBIAN_FRONTEND=noninteractive apt-get install -y -q unattended-upgrades >/dev/null 2>&1 || true
printf 'APT::Periodic::Update-Package-Lists "1";\nAPT::Periodic::Unattended-Upgrade "1";\n' > /etc/apt/apt.conf.d/20auto-upgrades
sed -i 's/^#\?PermitRootLogin.*/PermitRootLogin no/' /etc/ssh/sshd_config 2>/dev/null || true
ok "nightly backups (3:15 am, kept 14 days) and automatic security updates are on"

# ---------- 6. The first admin ----------
say "6 of 7  Your admin account"
HAVE_ADMIN="$(samba-tool group listmembers ClubAdmins 2>/dev/null || true)"
if [ -n "$HAVE_ADMIN" ]; then
  ok "an admin already exists: $(echo "$HAVE_ADMIN" | tr '\n' ' ')"
else
  echo "  This is the account YOU sign in to the admin page with. It is also an administrator on every laptop."
  while true; do
    ADMIN_USER="$(ask '  Pick your admin user name (letters and numbers, like coach.seth):')"
    read -r -s -p "  Pick a password (12 or more characters; nothing shows while you type): " P1 </dev/tty; echo
    read -r -s -p "  Type it again: " P2 </dev/tty; echo
    if [ "$P1" != "$P2" ]; then echo "  Those did not match. Try again."; continue; fi
    if [ "${#P1}" -lt 12 ]; then echo "  Use 12 or more characters for an admin. Try again."; continue; fi
    if CLUB_NEW_USER="$ADMIN_USER" CLUB_NEW_PASS="$P1" python3 -W ignore - <<'PYADMIN'
import os, sys
sys.path.insert(0, "/opt/club")
import clubd
clubd.init_db()
try:
    name = clubd.create_person(os.environ["CLUB_NEW_USER"], os.environ["CLUB_NEW_PASS"], "", "first admin", admin=True, need_email=False)
    clubd.audit("server setup", "made the first admin", name)
except clubd.Problem as p:
    print("  " + p.message)
    sys.exit(1)
PYADMIN
    then ok "admin account made"; break; else echo "  Try again."; fi
  done
  unset P1 P2
fi

# ---------- 7. Checks ----------
say "7 of 7  CHECKING IT ALL WORKS"
sleep 2
systemctl is-active --quiet club.service && ok "club program running" || bad "club program is not running (see /var/log/club.log)"
STATUS="$(curl -s --max-time 8 --cacert /etc/club/tls/ca.crt --resolve "$SERVER_NAME:$PORT:$IP" "https://$SERVER_NAME:$PORT/api/status" || true)"
has_text "$STATUS" '"open"' && ok "sign-up service answers over an encrypted connection" || bad "sign-up service does not answer (see /var/log/club.log)"
SHARES="$(smbclient -L localhost -N 2>/dev/null || true)"
has_text "$SHARES" "competition" && ok "competition share is visible" || bad "competition share is missing"
[ -d /srv/club/students ] && ok "student storage exists" || bad "student storage is missing"
samba-tool user show svc-join >/dev/null 2>&1 && ok "join account exists" || bad "join account is missing"

echo
if [ "$FAILS" = "0" ]; then printf '\033[1;32mALL DONE.\033[0m\n'; else printf '\033[1;31m%s check(s) failed - send a photo of this screen and the last lines of /var/log/club.log\033[0m\n' "$FAILS"; fi
echo "  Admin page:  https://$IP:$PORT   (from a computer on the laptop network)"
echo "    The browser will warn about the certificate on a computer that has not run Join-Club. That is expected."
echo "    Sign in with your admin user name and password. The first time, it walks you through the authenticator app."
echo "  Then: Settings > Download Join-Club.cmd, and run that file on ONE test laptop first."
